public class ImagenFija extends Trabajo {

    public ImagenFija(String codigo, String estudio, String proyecto,
                      double horasEstimadas, Horario horario) {

        // Inicializa los atributos comunes mediante el constructor de Trabajo.
        super(codigo, estudio, proyecto, horasEstimadas, horario);

        // Trabajo valida que las horas sean positivas.
        // Aquí se valida el límite específico de una imagen fija.
        if (horasEstimadas > 2) {
            throw new IllegalArgumentException(
                "Una imagen fija no puede superar las 2 horas estimadas."
            );
        }
    }

    // Calcula el precio fijo de la imagen según su horario.
    @Override
    public double calcularCosto() {
        // Comprueba si corresponde el precio diurno.
        if (horario == Horario.DIURNO) {
            // Devuelve el precio diurno, sin importar las horas estimadas.
            return 45.0;
        } else {
            // Devuelve el precio nocturno.
            return 30.0;
        }
    }

    // Devuelve el tiempo estimado de entrega en horas.
    @Override
    public int calcularTiempoEntrega() {
        // Selecciona el tiempo de entrega según el horario.
        if (horario == Horario.DIURNO) {
            // La entrega diurna se estima en 4 horas.
            return 4;
        } else {
            // La entrega nocturna se estima en 10 horas.
            return 10;
        }
    }

    // Indica el máximo de intentos, incluyendo el primero.
    @Override
    public int getIntentosMaximos() {
        return 3;
    }

    // Identifica la categoría para las consultas y los reportes.
    @Override
    public String getCategoria() {
        return "Imagen fija";
    }
}